CREATE TABLE `table_access` (
  `num` bigint NOT NULL AUTO_INCREMENT COMMENT '记录序号num\n,主键',
  `user_num` bigint NOT NULL COMMENT '人员序号num\n,外键',
  `service_num` int NOT NULL COMMENT '设备序号num\n,外键',
  `access_flag` tinyint NOT NULL COMMENT '进出标志位，1或2，1表示进，2表示出',
  `access_time` timestamp NOT NULL COMMENT '进出时间accessTime',
  `result` tinyint NOT NULL COMMENT '员工静电测试总结果，1"合格"2"不合格"3"免测"4"未测"5"禁测"',
  `unregist` tinyint DEFAULT NULL COMMENT '表示员工刷卡时（特殊的临时卡），是否已登记，未登记值为1，登记值为2',
  `will_fail` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '标示员工的手环、静电鞋是否即将失效。 如000表示没有失效的\n第1位表示手环是否失效，0表示没有即将失效，1表示即将失效\n第2位表示左脚静电鞋是否失效，0表示没有即将失效，1表示即将失效\n第3位表示右脚静电鞋是否失效，0表示没有即将失效，1表示即将失效',
  `result_hand_left` tinyint DEFAULT NULL COMMENT '左手测试结果，1"合格"2"不合格"3"免测"4"未测"5"禁测"',
  `value_hand_left` decimal(10,2) DEFAULT NULL COMMENT '左手测试实际阻值,单位:兆欧姆',
  `result_hand_right` tinyint DEFAULT NULL COMMENT '右手测试结果，"合格""不合格""免测""未测""禁测"',
  `value_hand_right` decimal(10,2) DEFAULT NULL COMMENT '右手测试实际阻值,单位:兆欧姆',
  `result_foot_left` tinyint DEFAULT NULL COMMENT '左脚测试结果，"合格""不合格""免测""未测""禁测"',
  `value_foot_left` decimal(10,2) DEFAULT NULL COMMENT '左脚测试实际阻值,单位:兆欧姆',
  `result_foot_right` tinyint DEFAULT NULL COMMENT '右脚测试结果，"合格""不合格""免测""未测""禁测"',
  `value_foot_right` decimal(10,2) DEFAULT NULL COMMENT '右脚测试实际阻值,单位:兆欧姆',
  `hand_left_min` decimal(10,2) DEFAULT NULL COMMENT '检测时左手下限阻值',
  `hand_left_max` decimal(10,2) DEFAULT NULL COMMENT '检测时左手上限阻值',
  `hand_right_min` decimal(10,2) DEFAULT NULL COMMENT '检测时右手下限阻值',
  `hand_right_max` decimal(10,2) DEFAULT NULL COMMENT '检测时右手上限阻值',
  `foot_left_min` decimal(10,2) DEFAULT NULL COMMENT '检测时左脚下限阻值',
  `foot_left_max` decimal(10,2) DEFAULT NULL COMMENT '检测时左脚上限阻值',
  `foot_right_min` decimal(10,2) DEFAULT NULL COMMENT '检测时右脚下限阻值',
  `foot_right_max` decimal(10,2) DEFAULT NULL COMMENT '检测时右脚上限阻值',
  PRIMARY KEY (`num`),
  KEY `service_num_access_foreign` (`service_num`),
  KEY `user_num_access_foreign` (`user_num`),
  CONSTRAINT `service_num_access_foreign` FOREIGN KEY (`service_num`) REFERENCES `table_service` (`num`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_num_access_foreign` FOREIGN KEY (`user_num`) REFERENCES `table_user` (`num`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
